import type { Metadata } from "next";
import TopBar from "@/components/TopBar";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollToTop from "@/components/ScrollToTop";
import ScrollReveal from "@/components/ScrollReveal";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata: Metadata = {
  title: {
    default: site.navbar.seo.title,
    template: `%s | ${site.navbar.brand.name}`,
  },
  description: site.navbar.seo.description,
};

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en"
      data-scroll-behavior="smooth"
      // Root font size: 16px, and from 1024px up it follows the 1440px design (1rem = 1/90 of the screen, at most 16px),
      // so laptops show the whole desktop layout scaled down; width only, so browser zoom keeps the same layout.
      // Tailwind v4 leaves buttons on the default cursor, so everything clickable gets the pointer.
      className={`${fontVariables} [font-size:16px] lg:[font-size:min(16px,calc(100vw/90))] scroll-smooth antialiased [&_:where(a[href],button:not(:disabled),select,summary,[role=button],[role=tab],label:has(input[type=radio]),label:has(input[type=checkbox]),input[type=date],input[type=radio],input[type=checkbox],input[type=submit])]:cursor-pointer [&_button:disabled]:cursor-not-allowed [&_input[type=date]::-webkit-calendar-picker-indicator]:cursor-pointer motion-reduce:scroll-auto motion-reduce:**:animate-none! motion-reduce:**:duration-[0.01ms]!`}
    >
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
      </head>
      <body className="min-h-screen bg-page font-sans text-ink wrap-break-word selection:bg-gold selection:text-white">
        <ScrollReveal />
        {/*
          The whole site sits in one frame, at most 1920px wide and centred. Up to 1920px it fills the
          screen, so nothing changes; on wider screens or when the browser is zoomed out the page stays
          in the middle with equal space on both sides instead of stretching.
        */}
        <div className="mx-auto flex min-h-screen w-full max-w-[120rem] flex-col overflow-x-clip bg-white">
          <TopBar data={site.navbar.topBar} contact={site.footer.contact} socials={site.footer.socials} />
          <Navbar data={site.navbar} contact={site.footer.contact} socials={site.footer.socials} />
          <main className="flex-1">
            <ScrollToTop>{children}</ScrollToTop>
          </main>
          <Footer data={site.footer} />
        </div>
      </body>
    </html>
  );
}
